Here is the commit message:
SOLR-10013: Fix DV range query bug introduced by LUCENE-7643
 by disabling and optimization (LUCENE-7649 to track re-enabling or removing
 completely)

Here is the root cause:
The bug was caused by an optimization in the handling of sorted and numeric document values that incorrectly assumed the presence of a singleton value, leading to incorrect behavior in range queries. This optimization was introduced in a previous change (LUCENE-7643) and resulted in null pointer exceptions or incorrect query results when the expected singleton was not present. The fix involved disabling this optimization to restore correct functionality for range queries.

Here is the patch:
 import java.util.Objects;

-import org.apache.lucene.index.DocValues;
 import org.apache.lucene.index.IndexReader;
 import org.apache.lucene.index.LeafReader;

   @Override
   public Weight createWeight(IndexSearcher searcher, boolean needsScores, float boost) throws IOException {
     return new ConstantScoreWeight(this, boost) {
       @Override
       public Scorer scorer(LeafReaderContext context) throws IOException {
         SortedSetDocValues values = getValues(context.reader(), field);
         if (values == null) {
           return null;
         }

         final long minOrd;
         if (lowerValue == null) {
           minOrd = 0;
         } else {
           final long ord = values.lookupTerm(lowerValue);
           if (ord < 0) {
             minOrd = -1 - ord;
           } else if (lowerInclusive) {
             minOrd = ord;
           } else {
             minOrd = ord + 1;
           }
         }

         final long maxOrd;
         if (upperValue == null) {
           maxOrd = values.getValueCount() - 1;
         } else {
           final long ord = values.lookupTerm(upperValue);
           if (ord < 0) {
             maxOrd = -2 - ord;
           } else if (upperInclusive) {
             maxOrd = ord;
           } else {
             maxOrd = ord - 1;
           }
         }

         if (minOrd > maxOrd) {
           return null;
         }

-        final SortedDocValues singleton = DocValues.unwrapSingleton(values);
+        final SortedDocValues singleton = null; // TODO: LUCENE-7649, re-consider optimization that broke SOLR-10013
+        // final SortedDocValues singleton = DocValues.unwrapSingleton(values);
         final TwoPhaseIterator iterator;
         if (singleton != null) {
+          assert false : "imposible code -- or: someone re-enabled singleton optinization w/o reading the whole method";
           iterator = new TwoPhaseIterator(singleton) {
             @Override
             public boolean matches() throws IOException {
               final long ord = singleton.ordValue();
               return ord >= minOrd && ord <= maxOrd;
             }

             @Override
             public float matchCost() {
               return 2; // 2 comparisons
             }
           };
         } else {
           iterator = new TwoPhaseIterator(values) {
             @Override
             public boolean matches() throws IOException {
               for (long ord = values.nextOrd(); ord != SortedSetDocValues.NO_MORE_ORDS; ord = values.nextOrd()) {
                 if (ord < minOrd) {
                   continue;
                 }
                 // Values are sorted, so the first ord that is >= minOrd is our best candidate
                 return ord <= maxOrd;
               }
               return false; // all ords were < minOrd
             }

             @Override
             public float matchCost() {
               return 2; // 2 comparisons
             }
           };
         }
         return new ConstantScoreScorer(this, score(), iterator);
       }
     };
   }



